#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static long long NQcnt;
static void NQrec(int cols,int d1,int d2,int full){if(cols==full){NQcnt++;return;}int avail=full&~(cols|d1|d2);while(avail){int p=avail&-avail;avail-=p;NQrec(cols|p,((d1|p)<<1)&full,(d2|p)>>1,full);}}
static long long NQ(int full){NQcnt=0;NQrec(0,0,0,full);return NQcnt;}
int main(void){long long n0;if(scanf("%lld",&n0)!=1)return 1;printf("%lld\n", NQ((1<<n0)-1));return 0;}
